import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------
# 1) Element‑wise addition custom CUDA kernel (FP32)
# ------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

# ------------------------------------------------------------
# 2) Custom matrix‑multiplication (GEMM) CUDA kernel
# ------------------------------------------------------------
matmul_kernel_source = """
__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // Each thread computes one element of C: row i, col j.
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < M && j < N) {
        float sum = 0.0f;
        for (int l = 0; l < K; ++l) {
            sum += A[i * K + l] * B[l * N + j];
        }
        C[i * N + j] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto out = torch.zeros(M, N, dtype=A.dtype);   // shape (M, N)

    const int block_size = 256;
    const int num_blocks_x = (N + block_size - 1) / block_size;
    const int num_blocks_y = (M + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks_y, block_size>>>(A.data_ptr<float>(), B.data_ptr<float()>, out.data_ptr<float()>, M, K, N);

    return out;
}
"""

# Load the inline functions
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
)

matmul = load_inline(
    name="matmul",
    cpp_sources="torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);",  # placeholder
    cuda_sources=matmul_kernel_source,
    functions=["matmul_cuda"],
    verbose=True,
)

# ------------------------------------------------------------
# Optimized model class (ModelNew)
# ------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add   # kept for completeness
        self.matmul_cuda = matmul                # custom matrix‑multiplication

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Args:
            A: Input tensor with shape (M, K).
            B: Input tensor with shape (K, N).

        Returns:
            C: Output tensor with shape (M, N), computed as C = A @ B.
        """
        return self.matmul_cuda(A, B)

